/**
 * A structured, serializable command error (#337). Serializes to
 * `{ "kind": …, "message": … }` so the frontend can tell an auth-required
 * state apart from a generic failure and show a clearer message, rather than
 * pattern-matching on a raw error string.
 *
 * Commands return `Result<T, AppError>`; because `AppError: From<String>`, an
 * existing `.map_err(|e| e.to_string())?` inside such a command still works —
 * `?` wraps the string as [`AppError::Message`].
 */
export type AppError =
  /**
   * No character is logged in, or a required ESI scope isn't granted.
   */
  | { kind: "authRequired"; message: string }
  /**
   * Any other failure, carrying a human-readable message.
   */
  | { kind: "message"; message: string };
/**
 * A logged-in EVE character in the roster. The refresh token lives in the OS
 * keychain (keyed by `character_id`), never here.
 */
export type Character = { characterId: number; name: string; scopes: string[] };
/**
 * The active character's currently-boarded ship: hull type id, its SDE name,
 * and the player-given ship name. `None` when there's no active character or
 * the fetch fails — most often the `esi-location.read_ship_type.v1` scope
 * isn't granted yet (re-login after enabling it on the EVE dev app). The
 * combat overlay uses this to auto-load your hull's fit (optimals) and drone
 * reminders.
 */
export type CharacterShip = {
  typeId: number;
  typeName: string;
  shipName: string;
};
/**
 * A blueprint owned by a character (or their corporation), with its real
 * ME/TE/runs.
 */
export type OwnedBlueprint = {
  characterId: number;
  characterName: string;
  /**
   * True for a corporation blueprint, false for a personal one.
   */
  corporation: boolean;
  typeId: number;
  /**
   * Blueprint name (resolved from the SDE), e.g. "Hobgoblin II Blueprint".
   */
  name: string;
  materialEfficiency: number;
  timeEfficiency: number;
  runs: number;
  quantity: number;
};

